Trigger.Source:
IF :CUSTOMER.NAME IS NULL OR TRIM(:CUSTOMER.NAME) IS NULL THEN
  MESSAGE('Name is mandatory. [BR-002]');
  RAISE FORM_TRIGGER_FAILURE;
END IF;

IF :CUSTOMER.EMAIL IS NULL OR TRIM(:CUSTOMER.EMAIL) IS NULL THEN
  MESSAGE('Email is mandatory. [BR-003]');
  RAISE FORM_TRIGGER_FAILURE;
END IF;
IF NOT REGEXP_LIKE(:CUSTOMER.EMAIL, '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$') THEN
  MESSAGE('Email format is invalid. [EC-004]');
  RAISE FORM_TRIGGER_FAILURE;
END IF;

IF :SYSTEM.RECORD_STATUS &lt;&gt; 'NEW' AND :CUSTOMER.CUSTOMER_ID IS NULL THEN
  MESSAGE('Customer was not found. [EC-005]');
  RAISE FORM_TRIGGER_FAILURE;
END IF;

DECLARE
  duplicate_count NUMBER;
BEGIN
  SELECT COUNT(*) INTO duplicate_count FROM CUSTOMER
   WHERE CUSTOMER_ID = :CUSTOMER.CUSTOMER_ID
      OR EMAIL = :CUSTOMER.EMAIL;
  IF duplicate_count &gt; 0 THEN
    MESSAGE('Customer ID or email must be unique. [BR-001] [BR-004]');
    RAISE FORM_TRIGGER_FAILURE;
  END IF;
END;

IF :CUSTOMER.CUSTOMER_ID IS NULL THEN
  MESSAGE('Customer ID cannot be modified after creation. [BR-006]');
  RAISE FORM_TRIGGER_FAILURE;
END IF;

IF :SYSTEM.RECORD_STATUS = 'NEW' THEN
  :CUSTOMER.ACTIVE := TRUE;
  SET_ITEM_PROPERTY('CUSTOMER.CUSTOMER_ID', UPDATE_ALLOWED, PROPERTY_TRUE);
ELSE
  SET_ITEM_PROPERTY('CUSTOMER.CUSTOMER_ID', UPDATE_ALLOWED, PROPERTY_FALSE);
END IF;

GO_BLOCK('CUSTOMER');
EXECUTE_QUERY;
IF :SYSTEM.LAST_RECORD = 'TRUE' AND :CUSTOMER.CUSTOMER_ID IS NULL THEN
  MESSAGE('Customer was not found. [EC-005]');
END IF;

GO_BLOCK('CUSTOMER');
IF :CUSTOMER.CUSTOMER_ID IS NULL THEN
  MESSAGE('Customer was not found. [EC-005]');
  RAISE FORM_TRIGGER_FAILURE;
END IF;
DELETE_RECORD;
COMMIT_FORM;

ProgramUnit.Source:
GO_BLOCK('CUSTOMER');
ENTER_QUERY;
-- Exact criteria: CUSTOMER_ID, NAME, EMAIL, CITY, COUNTRY.
-- Partial criteria: NAME, EMAIL, CITY, entered with query wildcards.
EXECUTE_QUERY;
